queries:
SELECT feerange, AVG(rebrate / feerate) FROM fees WHERE rebrate IS NOT NULL AND feerate IS NOT NULL AND feerate <> 0 GROUP BY feerange
SELECT feerange, AVG(rebrate) / AVG(feerate) AS avg_rebrate_feerate_ratio FROM fees GROUP BY feerange
SELECT feerange, SUM(rebrate) / SUM(feerate) AS avg_rebrate_feerate_ratio
FROM fees
GROUP BY feerange;
SELECT rebrate / feerate AS rebate_to_fee_ratio FROM fees WHERE feerate <> 0;
SELECT COUNT(*) AS fee_record_count
FROM fees f
JOIN orders o ON f.orderslink = o.recordvault
WHERE f.feetotal * 1.0 / NULLIF(o.notionsum, 0) IS NOT NULL;
